(function (window) {
    'use strict';

    // ─────────────────────────────────────────────────────
    //  CONSTANTS
    // ─────────────────────────────────────────────────────

    const VERSION             = '2.0.0';
    const MAX_RETRY_ATTEMPTS  = 3;
    const RETRY_BASE_DELAY_MS = 1000;

    const DEFAULT_CONFIG = {
        apiBaseUrl: 'http://localhost:5000',
        // Path to chatbot.css — override if you host it somewhere else
        cssUrl: '',
        endpoints: {
            createTicket:    '/api/ticket',
            transcribeAudio: '/api/transcribe'
        },
        position:    'bottom-right',
        primaryColor: '#259feb',
        chatbotName:  'Support Assistant',
        autoOpen:     false,

        enableErrorDetection: true,
        enableScreenshot:     true,
        enableVoiceRecording: true,

        maxFileSize:      5242880,  // 5 MB
        maxFiles:         5,
        maxAudioDuration: 120,      // seconds
        requestTimeout:   120000,    // 30 s

        allowedFileTypes: ['image/jpeg', 'image/png', 'image/gif', 'image/webp'],

        autoReportErrors: true,
        autoReportDelay:  2000,
        autoReportDefaults: {
            impact:   'SingleUser',
            urgency:  'CanWorkWithManyDifficulties',
            priority: 'High',
            category: 'Functional issue Report',
            contact:  'Auto-reported'
        },

        headers:         { 'Content-Type': 'application/json' },
        onTicketCreated: null,
        onError:         null,
        onOpen:          null,
        onClose:         null,
        onAutoReport:    null
    };

    // ─────────────────────────────────────────────────────
    //  TEMPLATE LIBRARY
    //
    //  Every HTML fragment lives here as a named factory.
    //  Render methods call these; no raw HTML strings outside
    //  this object.
    // ─────────────────────────────────────────────────────

    const TEMPLATES = {

        /* ── SVG icons (static) ──────────────────────── */

        ICON_CHAT: `
            <svg viewBox="0 0 24 24" aria-hidden="true">
                <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9
                         2-2V4c0-1.1-.9-2-2-2z"/>
            </svg>`,

        ICON_CHAT_SM: `
            <svg width="20" height="20" viewBox="0 0 24 24" fill="white" aria-hidden="true">
                <path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9
                         2-2V4c0-1.1-.9-2-2-2z"/>
            </svg>`,

        ICON_CLOSE: `×`,

        ICON_SEND: `
            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20"
                 viewBox="0 0 24 24" fill="none" stroke="currentColor"
                 stroke-width="2" aria-hidden="true">
                <path d="m22 2-7 20-4-9-9-4Z"/>
                <path d="M22 2 11 13"/>
            </svg>`,

        ICON_UPLOAD: `
            <svg viewBox="0 0 24 24" width="20" height="20"
                 stroke="currentColor" stroke-width="2" fill="none" aria-hidden="true">
                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/>
                <polyline points="17 8 12 3 7 8"/>
                <line x1="12" y1="3" x2="12" y2="15"/>
            </svg>`,

        ICON_CAMERA: `
            <svg viewBox="0 0 24 24" width="20" height="20"
                 stroke="currentColor" stroke-width="2" fill="none" aria-hidden="true">
                <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8
                         a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/>
                <circle cx="12" cy="13" r="4"/>
            </svg>`,

        ICON_MIC: `
            <svg viewBox="0 0 24 24" width="20" height="20"
                 stroke="currentColor" stroke-width="2" fill="none" aria-hidden="true">
                <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4
                         a3 3 0 0 0-3-3z"/>
                <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
                <line x1="12" y1="19" x2="12" y2="23"/>
                <line x1="8"  y1="23" x2="16" y2="23"/>
            </svg>`,

        ICON_CHECK: `
            <svg width="20" height="20" viewBox="0 0 24 24"
                 fill="white" aria-hidden="true">
                <path d="M20 6L9 17l-5-5"/>
            </svg>`,

        ICON_RESET: `
            <svg width="15" height="15" viewBox="0 0 24 24"
                 fill="none" stroke="currentColor" stroke-width="2.5"
                 stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <polyline points="1 4 1 10 7 10"/>
                <path d="M3.51 15a9 9 0 1 0 .49-4.95"/>
            </svg>`,

        LOADER: `<div class="loader" role="status" aria-label="Loading"></div>`,

        /* ── Main structural shells ───────────────────── */

        /**
         * Floating launcher button
         * @param {number} errorCount
         */
        launchButton: ({ errorCount }) => `
            <button class="chatbot-button"
                    onclick="window.supportChatbot.toggle()"
                    aria-label="Open support chat">
                ${TEMPLATES.ICON_CHAT}
                <div class="chatbot-error-badge"
                     style="display:${errorCount > 0 ? 'flex' : 'none'}"
                     aria-label="${errorCount} errors detected">
                    ${errorCount}
                </div>
            </button>`,

        /**
         * Outer chat window shell — content slots are injected as args
         * @param {string} chatbotName
         * @param {string} messagesHtml
         * @param {string} inputAreaHtml
         */
        window: ({ chatbotName, messagesHtml, inputAreaHtml }) => `
            <div class="chatbot-window open" role="dialog"
                 aria-label="${chatbotName} support chat">
                <div class="chatbot-header">
                    <div class="chatbot-header-title">
                        ${TEMPLATES.ICON_CHAT_SM}
                        <span>${chatbotName}</span>
                    </div>
                    <div class="chatbot-header-actions">
                        <button class="chatbot-reset-btn"
                                onclick="window.supportChatbot.confirmReset()"
                                title="Start over"
                                aria-label="Reset conversation">
                            ${TEMPLATES.ICON_RESET}
                        </button>
                        <button class="chatbot-close"
                                onclick="window.supportChatbot.toggle()"
                                aria-label="Close chat">
                            ${TEMPLATES.ICON_CLOSE}
                        </button>
                    </div>
                </div>
                <div class="chatbot-messages" id="chatbot-messages" aria-live="polite">
                    ${messagesHtml}
                </div>
                ${inputAreaHtml}
            </div>`,

        /* ── Message bubbles ──────────────────────────── */

        /**
         * @param {'bot'|'user'} sender
         * @param {string} textHtml   — already escaped + <br>-converted
         * @param {string} time
         */
        message: ({ sender, textHtml, time }) => `
            <div class="message ${sender}"
                 role="${sender === 'bot' ? 'log' : 'none'}">
                <div class="message-content">
                    ${textHtml}
                    <div class="message-time">${time}</div>
                </div>
            </div>`,

        loadingMessage: () => `
            <div class="message bot" role="status">
                <div class="message-content">
                    ${TEMPLATES.LOADER}
                </div>
            </div>`,

        /* ── Input area variants ─────────────────────── */

        /**
         * Full input area (shown during text-entry steps)
         * @param {string}  acceptTypes     comma-separated MIME types
         * @param {string}  imagePreviews   rendered preview HTML
         * @param {boolean} showScreenshot
         * @param {boolean} showVoice
         * @param {boolean} isRecording
         * @param {string}  inputPlaceholder
         */
        inputArea: ({ acceptTypes, imagePreviews, showScreenshot,
                      showVoice, isRecording, inputPlaceholder }) => `
            <div class="chatbot-input-area">
                ${imagePreviews}
                <div class="input-actions">
                    <input type="file" id="chatbot-file-input"
                           accept="${acceptTypes}" multiple style="display:none">
                    <button onclick="document.getElementById('chatbot-file-input').click()"
                            title="Upload image" class="action-btn"
                            aria-label="Upload image">
                        ${TEMPLATES.ICON_UPLOAD}
                    </button>
                    ${showScreenshot ? TEMPLATES.screenshotButton() : ''}
                    ${showVoice      ? TEMPLATES.micButton({ isRecording }) : ''}
                </div>
                <div class="input-row">
                    <textarea id="chatbot-input" class="chatbot-input"
                              placeholder="${inputPlaceholder}"
                              rows="3"
                              ${isRecording ? 'disabled' : ''}
                              aria-label="Message input"></textarea>
                </div>
                <div class="input-send-row">
                    <span class="input-hint">Ctrl+Enter to send</span>
                    <button onclick="window.supportChatbot.send()"
                            class="send-button"
                            ${isRecording ? 'disabled' : ''}
                            aria-label="Send message">
                        ${TEMPLATES.ICON_SEND}
                        Send
                    </button>
                </div>
            </div>`,

        /** Empty placeholder to keep layout consistent */
        emptyInputArea: () => `<div class="chatbot-input-area"></div>`,

        screenshotButton: () => `
            <button onclick="window.supportChatbot.captureScreenshot()"
                    title="Capture screenshot" class="action-btn"
                    aria-label="Capture screenshot">
                ${TEMPLATES.ICON_CAMERA}
            </button>`,

        /** @param {{ isRecording: boolean }} */
        micButton: ({ isRecording }) => `
            <button onclick="window.supportChatbot.toggleVoiceRecording()"
                    title="${isRecording ? 'Stop recording' : 'Record voice'}"
                    class="action-btn${isRecording ? ' recording' : ''}"
                    aria-label="${isRecording ? 'Stop recording' : 'Start voice recording'}">
                ${TEMPLATES.ICON_MIC}
            </button>`,

        /* ── Image previews ──────────────────────────── */

        /**
         * @param {{ name: string, data: string }[]} images
         * @param {Function} esc  — HTML escape helper
         */
        imagePreviews: ({ images, esc }) => {
            if (!images.length) return '';
            const items = images.map((img, i) => TEMPLATES.imagePreviewItem({ img, index: i, esc })).join('');
            return `<div class="image-preview">${items}</div>`;
        },

        /** @param {{ img, index: number, esc: Function }} */
        imagePreviewItem: ({ img, index, esc }) => `
            <div class="image-preview-item">
                <img src="${img.data}" alt="${esc(img.name)}" title="${esc(img.name)}">
                <button class="image-preview-remove"
                        onclick="window.supportChatbot.removeImage(${index})"
                        aria-label="Remove image">×</button>
            </div>`,

        /* ── Option groups (one per conversation step) ── */

        /**
         * Wrap an array of button strings in a container
         * @param {string} buttonsHtml
         * @param {string} [extraClass]
         */
        optionsContainer: ({ buttonsHtml, extraClass = '' }) => `
            <div class="options-container ${extraClass}">
                ${buttonsHtml}
            </div>`,

        /**
         * Single option button
         * @param {string}  onclick   — raw JS snippet (already-escaped)
         * @param {string}  label
         * @param {boolean} primary
         */
        optionButton: ({ onclick, label, primary = false }) => `
            <button class="option-button${primary ? ' primary' : ''}"
                    onclick="${onclick}">
                ${label}
            </button>`,

        /** Reset confirmation — rendered inline in message area */
        resetConfirm: () => TEMPLATES.optionsContainer({
            extraClass: 'reset-confirm-container',
            buttonsHtml: `
                <div class="reset-confirm-message">
                    ⚠️ This will clear all current progress and start over.
                </div>
                ${TEMPLATES.optionButton({
                    onclick: 'window.supportChatbot.reset()',
                    label:   '🔄 Yes, start over',
                    primary: true
                })}
                ${TEMPLATES.optionButton({
                    onclick: 'window.supportChatbot.cancelReset()',
                    label:   '↩️ No, keep going'
                })}`
        }),

        /** Greeting step */
        greetingOptions: () => TEMPLATES.optionsContainer({
            buttonsHtml: TEMPLATES.optionButton({
                onclick: 'window.supportChatbot.startReportIssue()',
                label:   '🛠 Open a support ticket',
                primary: true
            })
        }),

        /** After ticket submitted */
        newTicketOptions: () => TEMPLATES.optionsContainer({
            buttonsHtml: [
                TEMPLATES.optionButton({
                    onclick: "window.supportChatbot.handleNewTicketResponse('yes')",
                    label:   '✅ Yes, create another ticket',
                    primary: true
                }),
                TEMPLATES.optionButton({
                    onclick: "window.supportChatbot.handleNewTicketResponse('no')",
                    label:   "❌ No, I'm done"
                })
            ].join('')
        }),

        /**
         * Generic labelled-option list (impact / urgency / priority / category)
         * @param {string}              step
         * @param {{ id, label }[]|string[]} opts
         * @param {Function}            esc
         * @param {string}              [question]  — shown as a header above the buttons
         */
        labelledOptions: ({ step, opts, esc, question = '' }) => {
            const buttons = opts.map(o => {
                const id    = typeof o === 'string' ? o : o.id;
                const label = typeof o === 'string' ? o : o.label;
                return TEMPLATES.optionButton({
                    onclick: `window.supportChatbot.selectOption('${step}','${esc(id)}','${esc(label)}')`,
                    label:   esc(label)
                });
            }).join('');
            const header = question
                ? `<div class="step-question">${question}</div>`
                : '';
            return TEMPLATES.optionsContainer({ buttonsHtml: header + buttons });
        },

        /* ── Error selection ─────────────────────────── */

        /**
         * @param {{ _id, type, severity, message, timestamp, selected }[]} errors
         * @param {Function} esc
         * @param {Function} fmtTime
         */
        errorSelection: ({ errors, esc, fmtTime }) => {
            const rows = errors.map(e => TEMPLATES.errorRow({ error: e, esc, fmtTime })).join('');
            const actions = [
                TEMPLATES.optionButton({
                    onclick: 'window.supportChatbot.reportDetectedErrors()',
                    label:   '🐛 Report Selected',
                    primary: true
                }),
                TEMPLATES.optionButton({
                    onclick: 'window.supportChatbot.dismissErrors()',
                    label:   '❌ Dismiss All'
                })
            ].join('');

            return TEMPLATES.optionsContainer({
                extraClass: 'error-selection-container',
                buttonsHtml: `
                    <div class="error-select-header">Select errors to report:</div>
                    ${rows}
                    <div class="error-action-row">${actions}</div>`
            });
        },

        /**
         * Single error row with checkbox
         * @param {{ error, esc: Function, fmtTime: Function }}
         */
        errorRow: ({ error, esc, fmtTime }) => `
            <label class="error-checkbox-row">
                <input type="checkbox" class="error-checkbox"
                       ${error.selected !== false ? 'checked' : ''}
                       onchange="window.supportChatbot.toggleErrorSelection(${error._id})">
                <div class="error-checkbox-info">
                    <span class="error-type-badge ${esc(error.severity || 'medium')}">
                        ${esc(error.type)}
                    </span>
                    <span class="error-msg" title="${esc(error.message)}">
                        ${esc(error.message.substring(0, 80))}${error.message.length > 80 ? '…' : ''}
                    </span>
                    <span class="error-ts">${fmtTime(new Date(error.timestamp))}</span>
                </div>
            </label>`,

        /* ── Voice review ────────────────────────────── */

        /**
         * @param {string}  audioUrl
         * @param {string}  transcript
         * @param {Function} esc
         */
        voiceReview: ({ audioUrl, transcript, esc }) => {
            const transcriptBlock = transcript
                ? `<textarea id="voice-transcription-edit"
                             class="transcription-textarea"
                             rows="4"
                             placeholder="Transcription will appear here…">${esc(transcript)}</textarea>`
                : `<div class="transcription-empty">
                       ⚠️ No transcription — type your description below.
                   </div>
                   <textarea id="voice-transcription-edit"
                             class="transcription-textarea"
                             rows="4"
                             placeholder="Type your description here…"></textarea>`;

            const actions = [
                TEMPLATES.optionButton({
                    onclick: 'window.supportChatbot.useTranscription()',
                    label:   '✅ Use This',
                    primary: true
                }),
                TEMPLATES.optionButton({
                    onclick: 'window.supportChatbot.reRecord()',
                    label:   '🔄 Re-record'
                })
            ].join('');

            return TEMPLATES.optionsContainer({
                extraClass: 'voice-review-container',
                buttonsHtml: `
                    <div class="voice-review-section">
                        <div class="voice-review-label">🔊 Playback</div>
                        <audio controls src="${esc(audioUrl)}"
                               class="voice-audio-player"
                               preload="metadata"
                               aria-label="Recorded audio">
                            Your browser does not support audio playback.
                        </audio>
                    </div>
                    <div class="voice-review-section">
                        <div class="voice-review-label">
                            📝 Transcription
                            <span class="voice-hint">(edit if needed)</span>
                        </div>
                        ${transcriptBlock}
                    </div>
                    <div class="voice-review-actions">${actions}</div>`
            });
        },

        /* ── Ticket summary / confirmation ───────────── */

        /**
         * @param {object}  data         — ticketData
         * @param {number}  imageCount
         * @param {number}  errorCount
         * @param {Function} esc
         */
        ticketSummary: ({ data, imageCount, errorCount, esc }) => `
            <div class="ticket-summary" role="region" aria-label="Ticket summary">
                <h4>📋 Ticket Summary</h4>
                <p><strong>Title:</strong>       ${esc(data.title       || '—')}</p>
                <p><strong>Description:</strong> ${esc(data.description || '—')}</p>
                <p><strong>Impact:</strong>      ${esc(data.impact      || '—')}</p>
                <p><strong>Urgency:</strong>     ${esc(data.urgency     || '—')}</p>
                <p><strong>Priority:</strong>    ${esc(data.priority    || '—')}</p>
                <p><strong>Category:</strong>    ${esc(data.category    || '—')}</p>
                ${imageCount > 0
                    ? `<p><strong>Attachments:</strong> ${imageCount} file(s)</p>` : ''}
                ${errorCount > 0
                    ? `<p><strong>Linked errors:</strong> ${errorCount}</p>` : ''}
            </div>
            <button class="submit-button"
                    onclick="window.supportChatbot.submitTicket()">
                ${TEMPLATES.ICON_CHECK}
                Submit Ticket
            </button>`

    }; // end TEMPLATES

    // ─────────────────────────────────────────────────────
    //  HELPERS
    // ─────────────────────────────────────────────────────

    /** Fetch with timeout + exponential-backoff retries */
    async function safeFetch(url, options = {}, timeout = 120000, retries = MAX_RETRY_ATTEMPTS) {
        const ctrl = new AbortController();
        const tid  = setTimeout(() => ctrl.abort(), timeout);
        try {
            const response = await fetch(url, { ...options, signal: ctrl.signal });
            clearTimeout(tid);
            return response;
        } catch (err) {
            clearTimeout(tid);
            if (err.name === 'AbortError')
                throw new Error(`Request timed out after ${timeout / 1000}s`);
            if (retries > 0) {
                const delay = RETRY_BASE_DELAY_MS * (MAX_RETRY_ATTEMPTS - retries + 1);
                await new Promise(r => setTimeout(r, delay));
                return safeFetch(url, options, timeout, retries - 1);
            }
            throw err;
        }
    }

    /** Simple two-level config merge */
    function mergeConfig(defaults, overrides) {
        return {
            ...defaults,
            ...overrides,
            endpoints: {
                ...defaults.endpoints,
                ...(overrides.endpoints || {})
            },
            autoReportDefaults: {
                ...defaults.autoReportDefaults,
                ...(overrides.autoReportDefaults || {})
            }
        };
    }

    // ─────────────────────────────────────────────────────
    //  CLASS
    // ─────────────────────────────────────────────────────

    class SupportChatbot {

        constructor(userConfig = {}) {
            this._validateConfig(userConfig);
            this.config = mergeConfig(DEFAULT_CONFIG, userConfig);

            this._destroyed       = false;
            this._errorIdCounter  = 0;
            this._autoStopTimer   = null;
            this._recordingStream = null;

            this.state = {
                isOpen:       this.config.autoOpen,
                messages:     [],
                currentStep:  'greeting',
                ticketData:   this._initTicketData(),

                detectedErrors:     [],       // { _id, _sig, type, message, severity, selected, … }
                isLoading:          false,
                isSubmitting:       false,
                uploadedImages:     [],

                sessionId:          this._generateSessionId(),
                autoReportTimer:    null,
                autoReportedErrors: new Set(),

                // Voice
                isRecording:          false,
                mediaRecorder:        null,
                audioChunks:          [],
                recordingStartTime:   null,
                audioBlob:            null,
                audioUrl:             null,
                pendingTranscription: null
            };

            this.options   = this._initOptions();
            this.container = null;
            this._init();
        }

        // ════════════════════════════════════════════════
        //  BOOT
        // ════════════════════════════════════════════════

        _init() {
            try {
                this._loadExternalCSS();
                this._injectThemeVariables();
                this._createUI();
                if (this.config.enableErrorDetection) this._setupErrorDetection();
                if (this.state.isOpen) {
                    this.addMessage('bot',
                        `👋 Hello! I'm ${this.config.chatbotName}. How can I help you today?`);
                }
            } catch (err) {
                console.error('[SupportChatbot] Init failed:', err);
            }
        }

        _validateConfig(cfg) {
            if (cfg.apiBaseUrl && typeof cfg.apiBaseUrl !== 'string')
                throw new TypeError('[SupportChatbot] apiBaseUrl must be a string');
            if (cfg.primaryColor && !/^#[0-9A-Fa-f]{6}$/.test(cfg.primaryColor))
                console.warn('[SupportChatbot] primaryColor should be a 6-digit hex (#RRGGBB)');
        }

        _generateSessionId() {
            return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
        }

        _initTicketData() {
            return {
                title: '', impact: '', urgency: '', priority: '', category: '',
                description: '', contact: '', images: [], errors: [],
                metadata: {
                    userAgent: navigator.userAgent,
                    url:       window.location.href,
                    timestamp: new Date().toISOString(),
                    version:   VERSION
                }
            };
        }

        _initOptions() {
            return {
                impact: [
                    { id: 'SingleUser',   label: 'Single user' },
                    { id: 'GroupOfUsers', label: 'Group of users' },
                    { id: 'AllUsers',     label: 'All users' }
                ],
                urgency: [
                    { id: 'CanWorkNormally',             label: 'I can work normally anyway' },
                    { id: 'CanWorkWithSomeDifficulties', label: 'I can work with some difficulties' },
                    { id: 'CanWorkWithManyDifficulties', label: 'I can work but with many difficulties' },
                    { id: 'CannotWork',                  label: 'I cannot work' }
                ],
                priority: [
                    { id: 'Normal', label: 'Normal' },
                    { id: 'High',   label: 'High' }
                ],
                category: ['UI/UX', 'Functional issue Report', 'Other']
            };
        }

        // ════════════════════════════════════════════════
        //  CSS — external file + theme variables
        // ════════════════════════════════════════════════

        /**
         * Inject a <link> to chatbot.css if cssUrl is provided,
         * OR fall back to an auto-detected relative path beside chatbot.js.
         */
        _loadExternalCSS() {
            if (document.getElementById('support-chatbot-css')) return;

            let href = this.config.cssUrl;

            // Auto-detect: find the <script> that loaded us and derive a sibling CSS path
            if (!href) {
                const scripts = Array.from(document.querySelectorAll('script[src]'));
                const self    = scripts.find(s => /chatbot(\.min)?\.js(\?.*)?$/.test(s.src));
                if (self) {
                    href = self.src.replace(/chatbot(\.min)?\.js(\?.*)?$/, 'chatbot.css');
                }
            }

            if (!href) {
                // No external CSS found — theme will still apply via injected variables
                console.info('[SupportChatbot] No cssUrl configured. ' +
                             'Include chatbot.css manually or set config.cssUrl.');
                return;
            }

            const link  = document.createElement('link');
            link.id     = 'support-chatbot-css';
            link.rel    = 'stylesheet';
            link.href   = href;
            link.onerror = () =>
                console.warn(`[SupportChatbot] Could not load CSS from: ${href}`);
            document.head.appendChild(link);
        }

        /**
         * Inject a tiny <style> that sets CSS custom properties derived
         * from config.primaryColor and config.position.
         * Everything else lives in chatbot.css.
         */
        _injectThemeVariables() {
            if (document.getElementById('support-chatbot-theme')) return;

            const P  = this.config.primaryColor;
            const PD = this._adjustColor(P, -20);
            const PL = this._adjustColor(P,  80);
            const PH = this._adjustColor(P, -10);

            const posMap = {
                'bottom-right': { bottom: '20px', right:  '20px', top:  'auto', left:  'auto' },
                'bottom-left':  { bottom: '20px', left:   '20px', top:  'auto', right: 'auto' },
                'top-right':    { top:    '20px', right:  '20px', bottom: 'auto', left: 'auto' },
                'top-left':     { top:    '20px', left:   '20px', bottom: 'auto', right: 'auto' }
            };
            const pos = posMap[this.config.position] || posMap['bottom-right'];

            const style = document.createElement('style');
            style.id = 'support-chatbot-theme';
            style.textContent = `
                .support-chatbot {
                    --cb-primary:       ${P};
                    --cb-primary-dark:  ${PD};
                    --cb-primary-light: ${PL};
                    --cb-primary-hover: ${PH};
                    --cb-pos-bottom: ${pos.bottom};
                    --cb-pos-right:  ${pos.right};
                    --cb-pos-top:    ${pos.top};
                    --cb-pos-left:   ${pos.left};
                }
            `;
            document.head.appendChild(style);
        }

        // ════════════════════════════════════════════════
        //  ERROR DETECTION
        // ════════════════════════════════════════════════

        _setupErrorDetection() {
            const self = this;

            window.addEventListener('error', ev => {
                if (self._destroyed) return;
                if (ev.message === 'Script error.' && !ev.filename) return;
                self._captureError({
                    type: 'JavaScript Error',
                    message: ev.message || 'Unknown JS error',
                    file: ev.filename, line: ev.lineno, column: ev.colno,
                    stack: ev.error?.stack,
                    severity: 'high'
                });
            });

            window.addEventListener('unhandledrejection', ev => {
                if (self._destroyed) return;
                self._captureError({
                    type:     'Unhandled Promise',
                    message:  ev.reason?.message || String(ev.reason) || 'Unhandled rejection',
                    stack:    ev.reason?.stack,
                    severity: 'high'
                });
            });

            // Intercept fetch
            const _origFetch = window.fetch;
            window.fetch = async (...args) => {
                if (self._destroyed) return _origFetch(...args);
                try {
                    const res = await _origFetch(...args);
                    const url = (args[0]?.toString() || '').split('?')[0];
                    if (!self._isChatbotUrl(url) && !res.ok && res.status >= 400) {
                        self._captureError({
                            type:     `HTTP ${res.status}`,
                            message:  `${res.statusText || 'HTTP Error'} — ${url}`,
                            url, status: res.status,
                            severity: res.status >= 500 ? 'critical' : 'medium'
                        });
                    }
                    return res;
                } catch (err) {
                    const url = (args[0]?.toString() || '').split('?')[0];
                    if (!self._isChatbotUrl(url)) {
                        self._captureError({
                            type:     'Network Error',
                            message:  `Request failed: ${url}`,
                            severity: 'critical'
                        });
                    }
                    throw err;
                }
            };

            // Intercept XHR
            const _OrigXHR = window.XMLHttpRequest;
            window.XMLHttpRequest = function () {
                const xhr      = new _OrigXHR();
                const _origOpen = xhr.open.bind(xhr);
                let reqURL = '';
                xhr.open = function (method, url, ...rest) {
                    reqURL = url?.toString() || '';
                    return _origOpen(method, url, ...rest);
                };
                xhr.addEventListener('error', () => {
                    if (self._destroyed || self._isChatbotUrl(reqURL)) return;
                    self._captureError({
                        type: 'XHR Error', message: `Request failed: ${reqURL}`, severity: 'critical'
                    });
                });
                xhr.addEventListener('load', function () {
                    if (self._destroyed || self._isChatbotUrl(reqURL)) return;
                    if (this.status >= 400) {
                        self._captureError({
                            type:     `HTTP ${this.status}`,
                            message:  `${this.statusText || 'HTTP Error'} — ${reqURL}`,
                            status:   this.status,
                            severity: this.status >= 500 ? 'critical' : 'medium'
                        });
                    }
                });
                return xhr;
            };
        }

        _isChatbotUrl(url) {
            if (!url) return false;
            const { apiBaseUrl, endpoints } = this.config;
            return url.includes(endpoints.createTicket) ||
                   url.includes(endpoints.transcribeAudio) ||
                   url.includes(apiBaseUrl);
        }

        _captureError(raw) {
            if (this._destroyed) return;
            const sig = `${raw.type}||${raw.message}`;
            if (this.state.autoReportedErrors.has(sig)) return;
            if (this.state.detectedErrors.some(e => e._sig === sig)) return;

            this._errorIdCounter++;
            const error = {
                ...raw,
                _id:  this._errorIdCounter,
                _sig: sig,
                selected:  true,
                timestamp: raw.timestamp || new Date().toISOString()
            };
            this.state.detectedErrors.push(error);
            this._updateErrorBadge();

            if (this._shouldAutoReport(error)) {
                this._scheduleAutoReport(error, sig);
            } else if ((error.severity === 'critical' || error.severity === 'high') &&
                       this.state.currentStep !== 'error_selection') {
                this.open();
                this.state.currentStep = 'error_selection';
                this.addMessage('bot',
                    `⚠️ We detected ${this.state.detectedErrors.length} error(s).\n` +
                    `Select which to include in a report:`
                );
            }
        }

        _shouldAutoReport(error) {
            if (!this.config.autoReportErrors) return false;
            return ['HTTP 500','HTTP 502','HTTP 503','HTTP 504','Network Error','JavaScript Error']
                .some(t => error.type.includes(t));
        }

        _scheduleAutoReport(error, sig) {
            if (this.state.autoReportTimer) clearTimeout(this.state.autoReportTimer);
            this.state.autoReportTimer = setTimeout(() => {
                if (this._destroyed) return;
                const toReport = this.state.detectedErrors
                    .filter(e => !this.state.autoReportedErrors.has(e._sig));
                this._submitErrorReport(toReport, true);
            }, this.config.autoReportDelay);
        }

        toggleErrorSelection(id) {
            const err = this.state.detectedErrors.find(e => e._id === id);
            if (err) { err.selected = !err.selected; this._render(); }
        }

        reportDetectedErrors() {
            const selected = this.state.detectedErrors.filter(e => e.selected);
            if (!selected.length) {
                this.addMessage('bot', '⚠️ Please select at least one error to report.');
                return;
            }
            this._submitErrorReport(selected, false);
        }

        dismissErrors() {
            if (this.state.autoReportTimer) clearTimeout(this.state.autoReportTimer);
            this.state.detectedErrors = [];
            this.state.currentStep    = 'greeting';
            this._updateErrorBadge();
            this._render();
        }

        async _submitErrorReport(errors, isAutoReport) {
            if (!errors?.length || this.state.isSubmitting) return;
            this.state.isSubmitting = true;
            errors.forEach(e => this.state.autoReportedErrors.add(e._sig));

            if (!isAutoReport)
                this.addMessage('bot', `🐛 Submitting ${errors.length} error report(s)…`);

            this.state.isLoading   = true;
            this.state.currentStep = 'submitting_error';
            this._render();

            const primary    = errors[0];
            const ticketData = {
                ...this.config.autoReportDefaults,
                title:       `[Auto] ${primary.type}: ${primary.message.substring(0, 60)}`,
                description: this._buildErrorDescription(primary, errors),
                images:      [],
                errors,
                metadata: {
                    userAgent:    navigator.userAgent,
                    url:          window.location.href,
                    timestamp:    new Date().toISOString(),
                    sessionId:    this.state.sessionId,
                    autoReported: isAutoReport,
                    version:      VERSION
                }
            };

            try {
                const fd = new FormData();
                Object.entries(ticketData).forEach(([k, v]) => {
                    if (k === 'images') return;
                    fd.append(k, typeof v === 'string' ? v : JSON.stringify(v));
                });

                const res = await safeFetch(
                    `${this.config.apiBaseUrl}${this.config.endpoints.createTicket}`,
                    { method: 'POST', body: fd },
                    this.config.requestTimeout
                );
                if (!res.ok) {
                    const txt = await res.text().catch(() => '');
                    throw new Error(`Server ${res.status}: ${txt.substring(0, 120)}`);
                }

                const result = await res.json();
                this.state.isLoading    = false;
                this.state.isSubmitting = false;
                this.state.detectedErrors = [];
                this.state.currentStep    = 'greeting';
                this._updateErrorBadge();

                const how = isAutoReport ? 'automatically' : 'successfully';
                this.addMessage('bot',
                    `✅ Error(s) ${how} reported as ticket #${result.ticketId}. Our team will investigate.`
                );
                this._safeCallback('onTicketCreated', result.ticketId, ticketData);
                if (isAutoReport) this._safeCallback('onAutoReport', result.ticketId, ticketData);
                this._render();

            } catch (err) {
                console.error('[SupportChatbot] Error report failed:', err);
                this.state.isLoading    = false;
                this.state.isSubmitting = false;
                this.addMessage('bot', `❌ Report failed: ${err.message}. Please try again.`);
                this.state.currentStep = 'error_selection';
                this._render();
            }
        }

        _buildErrorDescription(primary, all = []) {
            const lines = [
                `Error Report — ${new Date().toLocaleString()}`, '',
                `Primary: [${primary.type}] ${primary.message}`,
                `Time   : ${primary.timestamp}`
            ];
            if (primary.url)    lines.push(`URL    : ${primary.url}`);
            if (primary.file)   lines.push(`File   : ${primary.file}:${primary.line}:${primary.column}`);
            if (primary.status) lines.push(`Status : ${primary.status}`);
            if (primary.stack)  lines.push(`Stack  :\n${primary.stack.substring(0, 600)}`);
            if (all.length > 1) {
                lines.push('', `All reported errors (${all.length}):`);
                all.forEach((e, i) => lines.push(`  ${i + 1}. [${e.type}] ${e.message}`));
            }
            lines.push('', `Session : ${this.state.sessionId}`, `Page    : ${window.location.href}`);
            return lines.join('\n');
        }

        _updateErrorBadge() {
            const badge = this.container?.querySelector('.chatbot-error-badge');
            if (!badge) return;
            const n = this.state.detectedErrors.length;
            badge.textContent = n;
            badge.style.display = n > 0 ? 'flex' : 'none';
        }

        // ════════════════════════════════════════════════
        //  VOICE RECORDING
        // ════════════════════════════════════════════════

        async startVoiceRecording() {
            if (this._destroyed || this.state.isRecording) return;
            if (!navigator.mediaDevices?.getUserMedia) {
                this.addMessage('bot', '❌ Voice recording not supported in this browser.');
                return;
            }
            this._cleanupAudio();
            this.state.isRecording = true;
            this.state.audioChunks = [];
            this.addMessage('bot', '🎤 Requesting microphone access…');
            this._render();

            try {
                const stream = await navigator.mediaDevices.getUserMedia({
                    audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 44100 }
                });
                this._recordingStream = stream;

                const mimeType = ['audio/webm;codecs=opus','audio/webm','audio/ogg','audio/mp4']
                    .find(t => MediaRecorder.isTypeSupported(t)) || '';
                this.state.mediaRecorder    = new MediaRecorder(stream, mimeType ? { mimeType } : {});
                this.state.recordingStartTime = Date.now();

                this.state.mediaRecorder.addEventListener('dataavailable', ev => {
                    if (ev.data?.size > 0) this.state.audioChunks.push(ev.data);
                });
                this.state.mediaRecorder.addEventListener('stop', () => {
                    if (!this._destroyed) this._finalizeRecording();
                });
                this.state.mediaRecorder.addEventListener('error', ev => {
                    console.error('[SupportChatbot] MediaRecorder error:', ev.error);
                    this.state.isRecording = false;
                    this.addMessage('bot', '❌ Recording error. Please try again.');
                    this._render();
                });

                this.state.mediaRecorder.start(250);

                const lastMsg = this.state.messages[this.state.messages.length - 1];
                if (lastMsg?.sender === 'bot')
                    lastMsg.text = '🎤 Recording… click the mic button to stop.';
                this._render();

                this._autoStopTimer = setTimeout(() => {
                    if (this.state.isRecording) {
                        this.addMessage('bot',
                            `⚠️ Max duration (${this.config.maxAudioDuration}s) reached.`);
                        this.stopVoiceRecording();
                    }
                }, this.config.maxAudioDuration * 1000);

            } catch (err) {
                console.error('[SupportChatbot] getUserMedia error:', err);
                this.state.isRecording = false;
                const msgMap = {
                    NotAllowedError:      '❌ Microphone access denied. Enable permissions and retry.',
                    NotFoundError:        '❌ No microphone found. Connect one and retry.',
                    NotReadableError:     '❌ Microphone in use by another app.',
                    SecurityError:        '❌ Microphone blocked by security policy.',
                    OverconstrainedError: '❌ Unsupported audio settings.'
                };
                this.addMessage('bot', msgMap[err.name] || `❌ Microphone error: ${err.message}`);
                this._render();
            }
        }

        stopVoiceRecording() {
            if (!this.state.isRecording || !this.state.mediaRecorder) return;
            if (this._autoStopTimer) { clearTimeout(this._autoStopTimer); this._autoStopTimer = null; }

            const duration = Math.floor((Date.now() - this.state.recordingStartTime) / 1000);
            if (duration < 1) {
                this.state.mediaRecorder.stop();
                this.state.isRecording = false;
                this._recordingStream?.getTracks().forEach(t => t.stop());
                this.addMessage('bot', '⚠️ Too short — record for at least 1 second.');
                this._render();
                return;
            }

            const lastMsg = this.state.messages[this.state.messages.length - 1];
            if (lastMsg?.sender === 'bot' && lastMsg.text.includes('Recording'))
                lastMsg.text = `⏹️ Stopped (${duration}s). Processing…`;

            this.state.mediaRecorder.stop();
            this.state.isRecording = false;
            this._recordingStream?.getTracks().forEach(t => t.stop());
            this.state.isLoading = true;
            this._render();
        }

        async _finalizeRecording() {
            const mimeType  = this.state.mediaRecorder?.mimeType || 'audio/webm';
            const audioBlob = new Blob(this.state.audioChunks, { type: mimeType });

            if (audioBlob.size < 500) {
                this.state.isLoading = false;
                this.addMessage('bot', '❌ Recording appears empty. Please try again.');
                this._render();
                return;
            }

            this.state.audioBlob = audioBlob;
            this.state.audioUrl  = URL.createObjectURL(audioBlob);

            try {
                this.state.pendingTranscription = await this._transcribeAudio(audioBlob) || '';
            } catch (err) {
                console.warn('[SupportChatbot] Transcription error:', err);
                this.state.pendingTranscription = '';
            }

            this.state.isLoading   = false;
            this.state.currentStep = 'voice_review';
            this.addMessage('bot', '🎧 Review your recording before submitting:');
            this._render();
        }

        useTranscription() {
            const textarea = this.container?.querySelector('#voice-transcription-edit');
            const text     = (textarea?.value || this.state.pendingTranscription || '').trim();

            if (!text) {
                this.state.currentStep = 'description';
                this._cleanupAudio();
                this._render();
                return;
            }

            this.state.ticketData.description = text;
            if (!this.state.ticketData.title) {
                this.state.ticketData.title = text.substring(0, 60) + (text.length > 60 ? '…' : '');
            }
            this._cleanupAudio();
            this.state.currentStep = 'impact';
            this._render();
        }

        reRecord() {
            this._cleanupAudio();
            this.state.currentStep = 'description';
            this._render();
        }

        _cleanupAudio() {
            if (this.state.audioUrl) URL.revokeObjectURL(this.state.audioUrl);
            this.state.audioUrl           = null;
            this.state.audioBlob          = null;
            this.state.pendingTranscription = null;
        }

        async _transcribeAudio(blob) {
            if (!this.config.endpoints.transcribeAudio)
                throw new Error('Transcription endpoint not configured');
            const ext = blob.type.includes('ogg') ? 'ogg'
                       : blob.type.includes('mp4') ? 'mp4' : 'webm';
            const fd = new FormData();
            fd.append('audio', blob, `recording.${ext}`);
            const res = await safeFetch(
                `${this.config.apiBaseUrl}${this.config.endpoints.transcribeAudio}`,
                { method: 'POST', body: fd },
                this.config.requestTimeout
            );
            if (!res.ok) {
                const txt = await res.text().catch(() => '');
                throw new Error(`Transcription API ${res.status}: ${txt.substring(0, 100)}`);
            }
            const result = await res.json();
            return result.transcription || result.text || '';
        }

        toggleVoiceRecording() {
            this.state.isRecording ? this.stopVoiceRecording() : this.startVoiceRecording();
        }

        // ════════════════════════════════════════════════
        //  SCREENSHOT — snipping-tool style
        //
        //  Flow:
        //    1. Show semi-transparent overlay over live page immediately
        //       (no html2canvas yet — zero delay, user sees real page)
        //    2. User drags to define region (or clicks Full Page)
        //    3. On confirm → hide chatbot → html2canvas with native
        //       x/y/width/height clip → restore chatbot → add to images
        // ════════════════════════════════════════════════

        async captureScreenshot() {
            if (this._destroyed) return;
            if (this.state.uploadedImages.length >= this.config.maxFiles) {
                this.addMessage('bot', `❌ Max ${this.config.maxFiles} files. Remove one first.`);
                return;
            }

            // Lazy-load html2canvas only when user actually confirms a capture
            // (not before — so we don't delay showing the overlay)
            this._showSnipOverlay();
        }

        _showSnipOverlay() {
            document.getElementById('chatbot-region-overlay')?.remove();

            // ── Overlay shell ──────────────────────────────
            const overlay = document.createElement('div');
            overlay.id = 'chatbot-region-overlay';
            Object.assign(overlay.style, {
                position: 'fixed', inset: '0', zIndex: '9999999',
                cursor: 'crosshair', userSelect: 'none', webkitUserSelect: 'none'
            });

            // Dimming layer — sits below the selection box
            const dim = document.createElement('div');
            Object.assign(dim.style, {
                position: 'absolute', inset: '0',
                background: 'rgba(0,0,0,0.45)',
                pointerEvents: 'none'
            });
            overlay.appendChild(dim);

            // ── Instruction banner ─────────────────────────
            const banner = document.createElement('div');
            banner.id = 'snip-banner';
            banner.textContent = '✂️  Drag to select a region  —  or use the buttons below';
            Object.assign(banner.style, {
                position: 'absolute', top: '16px', left: '50%',
                transform: 'translateX(-50%)',
                background: 'rgba(0,0,0,0.85)', color: '#fff',
                padding: '10px 24px', borderRadius: '8px',
                fontFamily: '-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif',
                fontSize: '14px', fontWeight: '500',
                whiteSpace: 'nowrap', pointerEvents: 'none', zIndex: '3',
                boxShadow: '0 2px 12px rgba(0,0,0,0.4)'
            });
            overlay.appendChild(banner);

            // ── Selection rectangle ────────────────────────
            // We use four "shade" divs to darken everything OUTSIDE the selection,
            // keeping the selected region at full brightness so the user sees
            // exactly what will be captured.
            const mkShade = () => {
                const d = document.createElement('div');
                Object.assign(d.style, {
                    position: 'absolute', background: 'rgba(0,0,0,0.5)',
                    pointerEvents: 'none', display: 'none'
                });
                overlay.appendChild(d);
                return d;
            };
            const shadeTop    = mkShade();
            const shadeBottom = mkShade();
            const shadeLeft   = mkShade();
            const shadeRight  = mkShade();

            // Selection border overlay
            const selBorder = document.createElement('div');
            Object.assign(selBorder.style, {
                position: 'absolute', display: 'none', pointerEvents: 'none',
                border: `2px solid ${this.config.primaryColor}`,
                boxSizing: 'border-box', zIndex: '2'
            });
            // Corner handles
            ['tl','tr','bl','br'].forEach(pos => {
                const h = document.createElement('div');
                Object.assign(h.style, {
                    position: 'absolute', width: '8px', height: '8px',
                    background: this.config.primaryColor, borderRadius: '1px',
                    ...(pos === 'tl' ? { top: '-4px',  left:  '-4px'  } : {}),
                    ...(pos === 'tr' ? { top: '-4px',  right: '-4px'  } : {}),
                    ...(pos === 'bl' ? { bottom: '-4px', left: '-4px' } : {}),
                    ...(pos === 'br' ? { bottom: '-4px', right: '-4px'} : {})
                });
                selBorder.appendChild(h);
            });
            overlay.appendChild(selBorder);

            // Dimensions label inside selection
            const dimLabel = document.createElement('div');
            Object.assign(dimLabel.style, {
                position: 'absolute', bottom: '6px', right: '6px',
                background: 'rgba(0,0,0,0.7)', color: '#fff',
                fontSize: '11px', fontFamily: 'monospace',
                padding: '2px 6px', borderRadius: '4px',
                pointerEvents: 'none', display: 'none', zIndex: '3'
            });
            selBorder.appendChild(dimLabel);

            // ── Button row ────────────────────────────────
            const btnRow = document.createElement('div');
            Object.assign(btnRow.style, {
                position: 'absolute', bottom: '28px',
                left: '50%', transform: 'translateX(-50%)',
                display: 'flex', gap: '10px', zIndex: '4'
            });

            const mkBtn = (txt, bg, visible = true) => {
                const b = document.createElement('button');
                b.innerHTML = txt;
                Object.assign(b.style, {
                    padding: '10px 20px', background: bg, color: '#fff',
                    border: 'none', borderRadius: '8px', cursor: 'pointer',
                    fontSize: '14px', fontWeight: '600',
                    display: visible ? 'inline-flex' : 'none',
                    alignItems: 'center', gap: '6px',
                    boxShadow: '0 2px 8px rgba(0,0,0,0.3)',
                    transition: 'opacity 0.15s'
                });
                b.addEventListener('mouseenter', () => b.style.opacity = '0.88');
                b.addEventListener('mouseleave', () => b.style.opacity = '1');
                return b;
            };

            const confirmBtn = mkBtn('✅ Capture Selection', '#10b981', false);
            const fullBtn    = mkBtn('📷 Capture Full Page', this.config.primaryColor);
            const cancelBtn  = mkBtn('✕ Cancel', '#6b7280');

            btnRow.append(confirmBtn, fullBtn, cancelBtn);
            overlay.appendChild(btnRow);

            // ── Drag logic ────────────────────────────────
            let dragging = false, x0 = 0, y0 = 0;
            let sel = null; // viewport coords {x,y,w,h}

            const getPos = e => {
                const src = e.touches ? e.touches[0] : e;
                return { x: src.clientX, y: src.clientY };
            };

            const updateShades = (x, y, w, h) => {
                const vw = window.innerWidth, vh = window.innerHeight;
                // Top shade
                Object.assign(shadeTop.style, {
                    display: 'block', left: '0', top: '0',
                    width: `${vw}px`, height: `${y}px`
                });
                // Bottom shade
                Object.assign(shadeBottom.style, {
                    display: 'block', left: '0', top: `${y + h}px`,
                    width: `${vw}px`, height: `${vh - y - h}px`
                });
                // Left shade
                Object.assign(shadeLeft.style, {
                    display: 'block', left: '0', top: `${y}px`,
                    width: `${x}px`, height: `${h}px`
                });
                // Right shade
                Object.assign(shadeRight.style, {
                    display: 'block', left: `${x + w}px`, top: `${y}px`,
                    width: `${vw - x - w}px`, height: `${h}px`
                });
                // Hide top-level dim when selection active (shades replace it)
                dim.style.display = 'none';
                // Update selection border
                Object.assign(selBorder.style, {
                    display: 'block',
                    left: `${x}px`, top: `${y}px`,
                    width: `${w}px`, height: `${h}px`
                });
                dimLabel.style.display = 'block';
                dimLabel.textContent = `${Math.round(w)} × ${Math.round(h)}`;
            };

            const onStart = e => {
                if (e.target.tagName === 'BUTTON') return;
                e.preventDefault();
                dragging = true;
                sel = null;
                confirmBtn.style.display = 'none';
                dim.style.display = 'block';
                [shadeTop, shadeBottom, shadeLeft, shadeRight].forEach(s => s.style.display = 'none');
                selBorder.style.display = 'none';
                ({ x: x0, y: y0 } = getPos(e));
            };

            const onMove = e => {
                if (!dragging) return;
                e.preventDefault();
                const { x, y } = getPos(e);
                const rx = Math.min(x, x0), ry = Math.min(y, y0);
                const rw = Math.abs(x - x0), rh = Math.abs(y - y0);
                updateShades(rx, ry, rw, rh);
            };

            const onEnd = e => {
                if (!dragging) return;
                dragging = false;
                const src = e.changedTouches ? e.changedTouches[0] : e;
                const x = src.clientX, y = src.clientY;
                const w = Math.abs(x - x0), h = Math.abs(y - y0);
                if (w > 10 && h > 10) {
                    sel = { x: Math.min(x, x0), y: Math.min(y, y0), w, h };
                    confirmBtn.style.display = 'inline-flex';
                    banner.textContent = '✅ Selection ready — click "Capture Selection" or drag again to redo';
                } else {
                    // Too small — reset
                    dim.style.display = 'block';
                    [shadeTop, shadeBottom, shadeLeft, shadeRight].forEach(s => s.style.display = 'none');
                    selBorder.style.display = 'none';
                }
            };

            overlay.addEventListener('mousedown',  onStart);
            overlay.addEventListener('mousemove',  onMove);
            overlay.addEventListener('mouseup',    onEnd);
            overlay.addEventListener('touchstart', onStart, { passive: false });
            overlay.addEventListener('touchmove',  onMove,  { passive: false });
            overlay.addEventListener('touchend',   onEnd);

            // ── Capture helpers ───────────────────────────
            const doCapture = async (clipRect) => {
                overlay.remove();
                if (this.container) this.container.style.visibility = 'hidden';

                // Small rAF delay so browser repaints before capture
                await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));

                try {
                    if (typeof html2canvas === 'undefined') {
                        await this._loadScript(
                            'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js'
                        );
                    }

                    // html2canvas native clip options handle the region for us
                    const opts = {
                        allowTaint: true, useCORS: true,
                        backgroundColor: '#ffffff', logging: false,
                        scale: window.devicePixelRatio || 1,
                        ignoreElements: el =>
                            el.classList?.contains('support-chatbot') ||
                            el.id === 'chatbot-region-overlay',
                        scrollX: -window.scrollX,
                        scrollY: -window.scrollY,
                        windowWidth:  window.innerWidth,
                        windowHeight: window.innerHeight
                    };

                    if (clipRect) {
                        // Add scroll offset to convert viewport → document coords
                        opts.x      = Math.round(clipRect.x + window.scrollX);
                        opts.y      = Math.round(clipRect.y + window.scrollY);
                        opts.width  = Math.round(clipRect.w);
                        opts.height = Math.round(clipRect.h);
                    }

                    const canvas = await html2canvas(document.body, opts);

                    if (this.container) this.container.style.visibility = 'visible';
                    this._saveCanvasAsImage(
                        canvas,
                        clipRect ? `screenshot_region_${Date.now()}.png`
                                 : `screenshot_full_${Date.now()}.png`
                    );

                } catch (err) {
                    console.error('[SupportChatbot] html2canvas error:', err);
                    if (this.container) this.container.style.visibility = 'visible';
                    this.addMessage('bot', `❌ Screenshot failed: ${err.message}. Upload manually.`);
                    this._render();
                }
            };

            confirmBtn.addEventListener('click', () => {
                if (!sel) return;
                doCapture(sel);
            });
            fullBtn.addEventListener('click',   () => doCapture(null));
            cancelBtn.addEventListener('click', () => {
                overlay.remove();
                this._render();
            });

            // Escape key cancels
            const onKey = e => {
                if (e.key === 'Escape') { overlay.remove(); this._render(); document.removeEventListener('keydown', onKey); }
            };
            document.addEventListener('keydown', onKey);

            document.body.appendChild(overlay);
        }

        /** Save a canvas element as a PNG and push to uploadedImages */
        _saveCanvasAsImage(canvas, name) {
            canvas.toBlob(blob => {
                if (!blob) {
                    this.addMessage('bot', '❌ Failed to process screenshot.');
                    this._render();
                    return;
                }
                if (this.state.uploadedImages.length >= this.config.maxFiles) {
                    this.addMessage('bot', `❌ Max ${this.config.maxFiles} files reached.`);
                    this._render();
                    return;
                }
                const file   = new File([blob], name, { type: 'image/png', lastModified: Date.now() });
                const reader = new FileReader();
                reader.onload  = e => {
                    this.state.ticketData.images.push(file);
                    this.state.uploadedImages.push({
                        name, type: 'image/png', size: blob.size,
                        data: e.target.result, isScreenshot: true,
                        uploadedAt: new Date().toISOString()
                    });
                    this.addMessage('bot', '✅ Screenshot added!');
                    this._render();
                };
                reader.onerror = () =>
                    this.addMessage('bot', '❌ Failed to read screenshot.');
                reader.readAsDataURL(blob);
            }, 'image/png');
        }

        _loadScript(src) {
            return new Promise((resolve, reject) => {
                if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
                const s = document.createElement('script');
                s.src     = src;
                s.onload  = resolve;
                s.onerror = () => reject(new Error(`Failed to load: ${src}`));
                document.head.appendChild(s);
            });
        }

        // ════════════════════════════════════════════════
        //  TICKET FLOW
        // ════════════════════════════════════════════════

        startReportIssue() {
            this.state.currentStep = 'description';
            this._render();
        }

        send() {
            const input = this.container?.querySelector('#chatbot-input');
            const msg   = input?.value.trim();
            if (!msg) return;
            this.addMessage('user', msg);
            input.value = '';

            const handlers = {
                description: () => {
                    if (msg.length < 5) {
                        this.addMessage('bot', '⚠️ Please provide a more detailed description.');
                        return false;
                    }
                    this.state.ticketData.description = msg;
                    if (!this.state.ticketData.title) {
                        this.state.ticketData.title = msg.substring(0, 60) + (msg.length > 60 ? '…' : '');
                    }
                    this.state.currentStep = 'impact';
                    this._render();
                    return true;
                },
                contact: () => {
                    // contact step no longer used — anonymous submissions only
                    return false;
                }
            };

            const handler = handlers[this.state.currentStep];
            if (handler) handler();
            this._scrollToBottom();
        }

        _validEmail(v) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v); }

        selectOption(step, value, label) {
            this.state.ticketData[step] = value;
            const map = {
                impact:   'urgency',
                urgency:  'priority',
                priority: 'category',
                category: 'confirmation'
            };
            if (map[step]) {
                this.state.currentStep = map[step];
                this._render();
                this._scrollToBottom();
            }
        }

        handleNewTicketResponse(resp) {
            if (resp === 'yes') {
                this.state.ticketData     = this._initTicketData();
                this.state.uploadedImages = [];
                this._cleanupAudio();
                this.state.currentStep = 'description';
                this._render();
            } else {
                this.state.currentStep = 'closed';
                setTimeout(() => {
                    if (!this._destroyed) {
                        this.state.currentStep = 'greeting';
                        this._render();
                    }
                }, 100);
            }
        }

        async submitTicket() {
            const { title, description } = this.state.ticketData;
            if (!title?.trim())       { this.addMessage('bot', '❌ Title is required.');       return; }
            if (!description?.trim()) { this.addMessage('bot', '❌ Description is required.'); return; }
            if (this.state.isSubmitting) { this.addMessage('bot', '⏳ Already submitting…'); return; }

            this.state.isSubmitting = true;

            const btn = this.container?.querySelector('.submit-button');
            if (btn) { btn.disabled = true; btn.innerHTML = `${TEMPLATES.LOADER} Submitting…`; }

            try {
                const fd = new FormData();
                Object.entries(this.state.ticketData).forEach(([k, v]) => {
                    if (k === 'images' || v === null || v === undefined) return;
                    fd.append(k, typeof v === 'string' || typeof v === 'number'
                        ? String(v) : JSON.stringify(v));
                });
                this.state.ticketData.images?.forEach(f => {
                    if (f instanceof File || f instanceof Blob)
                        fd.append('files', f, f.name || 'attachment.png');
                });

                const res = await safeFetch(
                    `${this.config.apiBaseUrl}${this.config.endpoints.createTicket}`,
                    { method: 'POST', body: fd },
                    this.config.requestTimeout
                );
                if (!res.ok) {
                    const txt = await res.text().catch(() => '');
                    throw new Error(`Server ${res.status}: ${txt.substring(0, 150)}`);
                }
                const result = await res.json();
                if (!result.ticketId) throw new Error('Invalid response: missing ticketId');

                this.state.isSubmitting = false;
                this.addMessage('bot', `✅ Ticket #${result.ticketId} created successfully!`);
                this._safeCallback('onTicketCreated', result.ticketId, this.state.ticketData);

                setTimeout(() => {
                    if (this._destroyed) return;
                    this.state.ticketData     = this._initTicketData();
                    this.state.uploadedImages = [];
                    this.state.detectedErrors = [];
                    this._cleanupAudio();
                    this.state.currentStep = 'new_ticket_prompt';
                    this._updateErrorBadge();
                    this._render();
                }, 2500);

            } catch (err) {
                console.error('[SupportChatbot] Submit error:', err);
                this.state.isSubmitting = false;
                this.addMessage('bot', `❌ Failed: ${err.message}`);
                this._safeCallback('onError', err);
                if (btn) {
                    btn.disabled = false;
                    btn.innerHTML = `${TEMPLATES.ICON_CHECK} Submit Ticket`;
                }
            }
        }

        // ════════════════════════════════════════════════
        //  FILE HANDLING
        // ════════════════════════════════════════════════

        handleFileUpload(event) {
            const files = Array.from(event.target.files || []);
            if (!files.length) return;

            const remaining = this.config.maxFiles - this.state.uploadedImages.length;
            if (remaining <= 0) {
                this.addMessage('bot', `❌ Max ${this.config.maxFiles} files reached. Remove one first.`);
                event.target.value = '';
                return;
            }

            files.slice(0, remaining).forEach(file => {
                if (!this.config.allowedFileTypes.includes(file.type)) {
                    this.addMessage('bot', `❌ Type not allowed: ${file.name} (${file.type})`);
                    return;
                }
                if (file.size > this.config.maxFileSize) {
                    const mb = (this.config.maxFileSize / 1048576).toFixed(1);
                    this.addMessage('bot', `❌ Too large: ${file.name} (max ${mb} MB)`);
                    return;
                }
                this.state.ticketData.images.push(file);
                const reader = new FileReader();
                reader.onload  = e => {
                    this.state.uploadedImages.push({
                        name: file.name, type: file.type, size: file.size,
                        data: e.target.result, uploadedAt: new Date().toISOString()
                    });
                    this._updateImagePreview();
                };
                reader.onerror = () =>
                    this.addMessage('bot', `❌ Could not read: ${file.name}`);
                reader.readAsDataURL(file);
            });

            if (files.length > remaining)
                this.addMessage('bot', `⚠️ Only ${remaining} file(s) added (limit reached).`);
            event.target.value = '';
        }

        removeImage(idx) {
            if (idx < 0 || idx >= this.state.uploadedImages.length) return;
            this.state.uploadedImages.splice(idx, 1);
            this.state.ticketData.images.splice(idx, 1);
            this._updateImagePreview();
        }

        _updateImagePreview() {
            const area = this.container?.querySelector('.chatbot-input-area');
            if (!area) return;
            area.querySelector('.image-preview')?.remove();
            if (this.state.uploadedImages.length > 0) {
                const preview = TEMPLATES.imagePreviews({
                    images: this.state.uploadedImages,
                    esc: this._esc.bind(this)
                });
                area.querySelector('.input-actions')?.insertAdjacentHTML('beforebegin', preview);
            }
        }

        // ════════════════════════════════════════════════
        //  RENDER — thin wrappers that call TEMPLATES
        // ════════════════════════════════════════════════

        _createUI() {
            this.container = document.createElement('div');
            this.container.className = 'support-chatbot';
            this.container.innerHTML = this._renderChatbot();
            document.body.appendChild(this.container);
            this._attachListeners();
        }

        _renderChatbot() {
            return this.state.isOpen ? this._renderWindow() : this._renderButton();
        }

        _renderButton() {
            return TEMPLATES.launchButton({
                errorCount: this.state.detectedErrors.length
            });
        }

        _renderWindow() {
            return TEMPLATES.window({
                chatbotName:  this._esc(this.config.chatbotName),
                messagesHtml: this._renderMessages() +
                              this._renderOptions() +
                              (this.state.isLoading ? TEMPLATES.loadingMessage() : ''),
                inputAreaHtml: this._renderInputArea()
            });
        }

        _renderMessages() {
            return this.state.messages.map(m =>
                TEMPLATES.message({
                    sender:   m.sender,
                    textHtml: this._esc(m.text).replace(/\n/g, '<br>'),
                    time:     this._fmtTime(m.timestamp)
                })
            ).join('');
        }

        /**
         * Returns the appropriate options HTML for the current step.
         * Each branch delegates to a named TEMPLATES factory — no inline HTML here.
         */
        _renderOptions() {
            const { currentStep: step, ticketData: data,
                    detectedErrors, uploadedImages, audioUrl,
                    pendingTranscription } = this.state;

            const esc     = this._esc.bind(this);
            const fmtTime = this._fmtTime.bind(this);

            const stepMap = {
                error_selection: () => TEMPLATES.errorSelection({ errors: detectedErrors, esc, fmtTime }),
                voice_review:    () => TEMPLATES.voiceReview({ audioUrl, transcript: pendingTranscription, esc }),
                reset_confirm:   () => TEMPLATES.resetConfirm(),
                closed:          () => '',
                greeting:        () => TEMPLATES.greetingOptions(),
                new_ticket_prompt: () => TEMPLATES.newTicketOptions(),
                contact_prompt:  () => '',
                impact:          () => TEMPLATES.labelledOptions({ step: 'impact',   opts: this.options.impact,   esc, question: 'Who is affected?' }),
                urgency:         () => TEMPLATES.labelledOptions({ step: 'urgency',  opts: this.options.urgency,  esc, question: 'How urgent is this?' }),
                priority:        () => TEMPLATES.labelledOptions({ step: 'priority', opts: this.options.priority, esc, question: 'What priority?' }),
                category:        () => TEMPLATES.labelledOptions({ step: 'category', opts: this.options.category, esc, question: 'Select a category:' }),
                confirmation:    () => TEMPLATES.ticketSummary({
                    data,
                    imageCount: uploadedImages.length,
                    errorCount: detectedErrors.length,
                    esc
                })
            };

            return (stepMap[step] ?? (() => ''))();
        }

        _renderInputArea() {
            const showInput = ['description'].includes(this.state.currentStep);
            if (!showInput) return TEMPLATES.emptyInputArea();

            const placeholderMap = {
                description: 'Describe the issue…'
            };

            return TEMPLATES.inputArea({
                acceptTypes:       this.config.allowedFileTypes.join(','),
                imagePreviews:     TEMPLATES.imagePreviews({
                    images: this.state.uploadedImages,
                    esc:    this._esc.bind(this)
                }),
                showScreenshot:    this.config.enableScreenshot,
                showVoice:         this.config.enableVoiceRecording &&
                                   this.state.currentStep === 'description',
                isRecording:       this.state.isRecording,
                inputPlaceholder:  placeholderMap[this.state.currentStep] || 'Type a message…'
            });
        }

        // ════════════════════════════════════════════════
        //  UI LIFECYCLE
        // ════════════════════════════════════════════════

        _render() {
            if (!this.container || this._destroyed) return;
            const msgDiv       = this.container.querySelector('#chatbot-messages');
            const wasAtBottom  = !msgDiv ||
                (msgDiv.scrollHeight - msgDiv.scrollTop <= msgDiv.clientHeight + 60);

            this.container.innerHTML = this._renderChatbot();
            this._attachListeners();
            this._updateErrorBadge();

            if (wasAtBottom) setTimeout(() => this._scrollToBottom(), 0);
        }

        _attachListeners() {
            const input     = this.container?.querySelector('#chatbot-input');
            const fileInput = this.container?.querySelector('#chatbot-file-input');

            if (input) {
                // Ctrl+Enter or Cmd+Enter → submit; plain Enter → newline (textarea default)
                input.addEventListener('keydown', e => {
                    if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
                        e.preventDefault();
                        this.send();
                    }
                });
                // Auto-grow: reset to 1 row, then expand to fit content (max via CSS)
                input.addEventListener('input', () => {
                    input.style.height = 'auto';
                    input.style.height = input.scrollHeight + 'px';
                });
            }

            if (fileInput) fileInput.addEventListener('change', e => this.handleFileUpload(e));
        }

        addMessage(sender, text) {
            this.state.messages.push({ sender, text, timestamp: new Date() });
            this._render();
            this._scrollToBottom();
        }

        toggle() {
            this.state.isOpen = !this.state.isOpen;
            if (this.state.isOpen) {
                if (!this.state.messages.length)
                    this.addMessage('bot',
                        `👋 Hello! I'm ${this.config.chatbotName}. How can I help you today?`);
                this._safeCallback('onOpen');
            } else {
                this._safeCallback('onClose');
            }
            this._render();
        }

        open()  { if (!this.state.isOpen) this.toggle(); }
        close() { if (this.state.isOpen)  this.toggle(); }

        // ── Reset ─────────────────────────────────────────

        /** Show in-chat confirmation before wiping state */
        confirmReset() {
            // Don't show confirm if already at greeting with no progress
            const isAtStart = this.state.currentStep === 'greeting' &&
                              this.state.messages.length <= 1 &&
                              !this.state.ticketData.title &&
                              !this.state.ticketData.description;
            if (isAtStart) return;

            // Clear any pending confirm already in view to avoid stacking
            if (this.state.currentStep === 'reset_confirm') {
                this.cancelReset();
                return;
            }

            const prevStep = this.state.currentStep;
            this.state._preResetStep = prevStep;
            this.state.currentStep   = 'reset_confirm';
            this._render();
        }

        cancelReset() {
            this.state.currentStep = this.state._preResetStep || 'greeting';
            this.state._preResetStep = null;
            this._render();
        }

        /** Hard reset — wipes everything and returns to greeting */
        reset() {
            // Stop timers
            if (this.state.autoReportTimer) clearTimeout(this.state.autoReportTimer);
            if (this._autoStopTimer)        clearTimeout(this._autoStopTimer);
            this._autoStopTimer = null;

            // Stop any active recording
            if (this.state.isRecording && this.state.mediaRecorder) {
                try { this.state.mediaRecorder.stop(); } catch (_) {}
            }
            this._recordingStream?.getTracks().forEach(t => t.stop());
            this._recordingStream = null;

            // Clean audio blobs
            this._cleanupAudio();

            // Remove screenshot overlay if open
            document.getElementById('chatbot-region-overlay')?.remove();

            // Reset all state
            this.state = {
                ...this.state,                          // keep sessionId, autoReportedErrors
                messages:             [],
                currentStep:          'greeting',
                ticketData:           this._initTicketData(),
                detectedErrors:       [],
                isLoading:            false,
                isSubmitting:         false,
                uploadedImages:       [],
                autoReportTimer:      null,
                isRecording:          false,
                mediaRecorder:        null,
                audioChunks:          [],
                recordingStartTime:   null,
                audioBlob:            null,
                audioUrl:             null,
                pendingTranscription: null,
                _preResetStep:        null
            };

            this._updateErrorBadge();
            this.addMessage('bot',
                `👋 Let's start fresh! I'm ${this.config.chatbotName}. How can I help you today?`
            );
        }

        destroy() {
            this._destroyed = true;
            if (this.state.autoReportTimer) clearTimeout(this.state.autoReportTimer);
            if (this._autoStopTimer)        clearTimeout(this._autoStopTimer);
            if (this.state.isRecording && this.state.mediaRecorder) this.stopVoiceRecording();
            this._cleanupAudio();
            document.getElementById('chatbot-region-overlay')?.remove();
            this.container?.remove();
        }

        // ════════════════════════════════════════════════
        //  PURE HELPERS
        // ════════════════════════════════════════════════

        _safeCallback(name, ...args) {
            if (typeof this.config[name] === 'function') {
                try { this.config[name](...args); }
                catch (e) { console.warn(`[SupportChatbot] ${name} callback threw:`, e); }
            }
        }

        _scrollToBottom() {
            const d = this.container?.querySelector('#chatbot-messages');
            if (d) d.scrollTop = d.scrollHeight;
        }

        /** HTML-escape a string */
        _esc(str) {
            if (str == null) return '';
            const d = document.createElement('div');
            d.textContent = String(str);
            return d.innerHTML;
        }

        /** Format a Date to HH:MM */
        _fmtTime(date) {
            try { return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); }
            catch { return ''; }
        }

        /** Lighten (+) or darken (-) a #RRGGBB hex colour */
        _adjustColor(hex, amount) {
            const clamp = v => Math.min(Math.max(v, 0), 255);
            const n = parseInt(hex.replace('#', ''), 16);
            const r = clamp((n >> 16)        + amount);
            const g = clamp(((n >> 8) & 0xFF) + amount);
            const b = clamp((n & 0xFF)        + amount);
            return '#' + (0x1000000 + (r << 16) + (g << 8) + b).toString(16).slice(1);
        }

    } // end SupportChatbot

    // ─────────────────────────────────────────────────────
    //  EXPORT
    // ─────────────────────────────────────────────────────

    window.SupportChatbot = SupportChatbot;

    if (window.chatbotConfig) {
        try {
            window.supportChatbot = new SupportChatbot(window.chatbotConfig);
        } catch (err) {
            console.error('[SupportChatbot] Auto-init failed:', err);
        }
    }

})(window);